{
  "name": "树莓派相机",
  "name_en": "Raspberry Pi Camera",
  "manufacturer": "Raspberry Pi",
  "description": "一款通过 REST API 控制的树莓派相机，用于实验中的图像采集、单张拍照、预览图获取和实时观察，并可设置 ISO 与曝光时间等成像参数。",
  "description_en": "A Raspberry Pi camera controlled through a REST API, used in laboratory setups for image acquisition, snapshot capture, preview retrieval, and live viewing, with configurable imaging parameters such as ISO and exposure time.",
  "actions": [
    {
      "action_name": "auto-isConnected",
      "description": "检查相机是否已连接。",
      "description_en": "Check whether the camera is connected."
    },
    {
      "action_name": "auto-get_json",
      "description": "向相机 REST 接口发送 HTTP GET 请求并返回 JSON 响应。",
      "description_en": "Send an HTTP GET request to the camera REST interface and return the JSON response."
    },
    {
      "action_name": "auto-post_json",
      "description": "向相机 REST 接口发送 HTTP POST 请求并返回 JSON 响应。",
      "description_en": "Send an HTTP POST request to the camera REST interface and return the JSON response."
    },
    {
      "action_name": "auto-set_iso",
      "description": "设置 ISO 参数。",
      "description_en": "Set the ISO setting."
    },
    {
      "action_name": "auto-get_iso",
      "description": "获取 ISO 参数。",
      "description_en": "Get the ISO setting."
    },
    {
      "action_name": "auto-set_exposuretime",
      "description": "设置曝光时间。",
      "description_en": "Set the exposure time."
    },
    {
      "action_name": "auto-get_exposuretime",
      "description": "获取曝光时间。",
      "description_en": "Get the exposure time."
    },
    {
      "action_name": "auto-get_snap",
      "description": "采集一张快照图像。",
      "description_en": "Capture a snapshot image."
    },
    {
      "action_name": "auto-get_resolution_preview",
      "description": "获取预览图像的分辨率。",
      "description_en": "Get the preview image resolution."
    },
    {
      "action_name": "auto-get_preview",
      "description": "获取当前预览图像。",
      "description_en": "Get the current preview image."
    },
    {
      "action_name": "auto-start_live",
      "description": "启动实时预览或实时成像。",
      "description_en": "Start live preview or live imaging."
    },
    {
      "action_name": "auto-stop_live",
      "description": "停止实时预览或实时成像。",
      "description_en": "Stop live preview or live imaging."
    }
  ],
  "tag_hints": [
    "Raspberry Pi camera",
    "REST camera control",
    "image acquisition",
    "live preview",
    "snapshot capture",
    "ISO control",
    "exposure time control"
  ]
}

